RATES = {"USD": 1.0, "EUR": 0.92, "GBP": 0.79, "BDT": 121.5}


def fx_convert(amount: float, source: str, target: str) -> dict:
    """Convert an amount between two currencies at a fixed demo rate."""
    if source not in RATES or target not in RATES:
        raise ValueError(f"Unsupported currency pair {source}->{target}")
    converted = amount / RATES[source] * RATES[target]
    return {"amount": round(converted, 2), "currency": target, "rate": RATES[target] / RATES[source]}

